const p = msg.payload || {};
const parsedTs = Date.parse(p.ts);
const t = Number.isFinite(parsedTs) ? parsedTs : Date.now();
const lines = [];

if (Array.isArray(p.buses)) {
  for (const b of p.buses) {
    if (b && b.bus_idx != null) {
      const tags = [
        `bus_id=${b.bus_idx}`,
        `name=${String(b.name).replace(/[,\s]/g, '_')}`,
      ]
      const fields = [
        ...(b.vm_pu != null ? [`vm_pu=${Number(b.vm_pu)}`] : []),
        ...(b.va_degree != null ? [`va_deg=${Number(b.va_degree)}`] : []),
        ...(b.p_mw != null ? [`p_mw=${Number(b.p_mw)}`] : []),
        ...(b.q_mvar != null ? [`q_mvar=${Number(b.q_mvar)}`] : []),
        `energized=${!!b.energized}`,
        ...(b.quality != null ? [`quality=${JSON.stringify(b.quality)}`] : [])
      ].join(",");
      if (fields) lines.push(`bus,${tags} ${fields} ${t}`);
    }
  }
}

if (Array.isArray(p.lines)) {
  for (const l of p.lines) {
    if (!l || !l.name) continue;
    const tags = [
      `line_id=${l.line_idx}`,
      `name=${String(l.name).replace(/[,\s]/g, '_')}`,
      `end=${String(l.end)}`,
      `from_bus=${String(l.from_bus)}`,
      `to_bus=${String(l.to_bus)}`,
    ].join(",");
    const fields = [
      ...(l.p_mw != null ? [`p_mw=${Number(l.p_mw)}`] : []),
      ...(l.pl_mw != null ? [`pl_mw=${Number(l.pl_mw)}`] : []),
      ...(l.q_mvar != null ? [`q_mvar=${Number(l.q_mvar)}`] : []),
      ...(l.ql_mvar != null ? [`ql_mvar=${Number(l.ql_mvar)}`] : []),
      ...(l.i_ka != null ? [`i_ka=${Number(l.i_ka)}`] : []),
      ...(l.vm_pu != null ? [`vm_pu=${Number(l.vm_pu)}`] : []),
      ...(l.va_degree != null ? [`va_deg=${Number(l.va_degree)}`] : []),
      ...(l.loading_percent != null ? [`loading_percent=${Number(l.loading_percent)}`] : []),
      `energized=${!!l.energized}`,
      ...(l.quality != null ? [`quality=${JSON.stringify(l.quality)}`] : [])
    ].join(",");
    if (fields) lines.push(`line,${tags} ${fields} ${t}`);
  }
}

if (Array.isArray(p.transformers)) {
  for (const tr of p.transformers) {
    if (!tr || tr.transformer_idx == null || !tr.name) continue;
    const tags = [
      `transformer_id=${tr.transformer_idx}`,
      `name=${String(tr.name).replace(/[,\s]/g, '_')}`,
      `hv_bus=${String(tr.hv_bus)}`,
      `lv_bus=${String(tr.lv_bus)}`,
    ].join(",");
    const fields = [
      ...(tr.p_hv_mw != null ? [`p_hv_mw=${Number(tr.p_hv_mw)}`] : []),
      ...(tr.q_hv_mvar != null ? [`q_hv_mvar=${Number(tr.q_hv_mvar)}`] : []),
      ...(tr.p_lv_mw != null ? [`p_lv_mw=${Number(tr.p_lv_mw)}`] : []),
      ...(tr.q_lv_mvar != null ? [`q_lv_mvar=${Number(tr.q_lv_mvar)}`] : []),
      ...(tr.i_hv_ka != null ? [`i_hv_ka=${Number(tr.i_hv_ka)}`] : []),
      ...(tr.i_lv_ka != null ? [`i_lv_ka=${Number(tr.i_lv_ka)}`] : []),
      ...(tr.vm_hv_pu != null ? [`vm_hv_pu=${Number(tr.vm_hv_pu)}`] : []),
      ...(tr.vm_lv_pu != null ? [`vm_lv_pu=${Number(tr.vm_lv_pu)}`] : []),
      ...(tr.va_hv_degree != null ? [`va_hv_deg=${Number(tr.va_hv_degree)}`] : []),
      ...(tr.va_lv_degree != null ? [`va_lv_deg=${Number(tr.va_lv_degree)}`] : []),
      ...(tr.loading_percent != null ? [`loading_percent=${Number(tr.loading_percent)}`] : []),
      `energized=${!!tr.energized}`,
      ...(tr.quality != null ? [`quality=${JSON.stringify(tr.quality)}`] : [])
    ].join(",");
    if (fields) lines.push(`transformer,${tags} ${fields} ${t}`);
  }
}

if (p.ext_grid && (p.ext_grid.p_mw != null || p.ext_grid.q_mvar != null)) {
  const tags = `grid_id=${p.ext_grid.grid_idx},name=${String(p.ext_grid.name).replace(/[,\s]/g, '_')}`;
  const fields = [
    ...(p.ext_grid.p_mw != null ? [`p_mw=${Number(p.ext_grid.p_mw)}`] : []),
    ...(p.ext_grid.q_mvar != null ? [`q_mvar=${Number(p.ext_grid.q_mvar)}`] : [])
  ].join(",");
  lines.push(`ext_grid,${tags} ${fields} ${t}`);
}

msg.payload = lines.join("\n");
return msg;

// Persist only the simulator's authoritative breaker/protection status.
const p = msg.payload || {};
const timestamp = Date.parse(p.ts);
const breaker = String(p.breaker || "");
const state = String(p.state || "").toUpperCase();
const knownBreakers = ["BRK_F1", "BRK_R1"];

if (!Number.isFinite(timestamp)) {
    node.warn("Ignoring breaker status without a valid timestamp");
    return null;
}
if (!knownBreakers.includes(breaker) ||
    (state !== "OPEN" && state !== "CLOSED") ||
    typeof p.tripped !== "boolean" ||
    typeof p.undervoltage_alarm !== "boolean") {
    node.warn("Ignoring malformed authoritative breaker status");
    return null;
}

const tripReason = p.trip_reason == null ? "" : String(p.trip_reason);
const fields = [
    `state=${JSON.stringify(state)}`,
    `tripped=${p.tripped}`,
    `undervoltage_alarm=${p.undervoltage_alarm}`,
    `trip_reason=${JSON.stringify(tripReason)}`
];

msg.payload = `breaker_status,breaker=${breaker} ${fields.join(",")} ${timestamp}`;
return msg;

const prev = context.get('prev');
const online = msg.payload && msg.payload.online === true;
if (prev === online) return [null, null];
context.set('prev', online);
const outText = { topic: 'display/presence', payload: online ? 'ONLINE' : 'OFFLINE' };
const outToast = prev === undefined ? null : {
    topic: 'Plant', payload: online ? 'Plant ONLINE' : 'Plant OFFLINE',
    position: 'top right', timeout: 3
};
return [outText, outToast];

const url = env.get('INFLUXDB_URL')
const bucket = env.get('INFLUXDB_BUCKET')
const org = env.get('INFLUXDB_ORG')
const token = env.get('INFLUXDB_WRITE_TOKEN')

msg.headers = {
  Authorization: `Token ${token}`,
  "Content-Type": "text/plain"
};
msg.url = `${url}/api/v2/write?org=${org}&bucket=${bucket}&precision=ms`;
return msg;

const p = msg.payload || {};
const timestamp = Date.parse(p.ts);
const identity = {BRK_F1: "IED_F1", BRK_R1: "IED_R1"};
const events = ["PICKUP", "TIMING_STARTED", "TIMING_CANCELLED", "TRIP_REQUEST",
    "OPERATION_REQUEST", "POSITION_FEEDBACK", "RESET", "CLOSE_REJECTED"];
if (!Number.isFinite(timestamp) || identity[p.breaker] !== p.ied ||
    !events.includes(p.event) || typeof p.event_id !== "string" ||
    !/^[a-f0-9]{32}:[1-9][0-9]*$/.test(p.event_id) ||
    !["OPEN", "CLOSED"].includes(p.position) ||
    typeof p.tripped !== "boolean" ||
    !Number.isFinite(p.scan_monotonic_s)) {
    node.warn("Ignoring malformed IED event");
    return null;
}
const tag = value => String(value).replace(/\\/g, "\\\\").replace(/([ ,=])/g, "\\$1");
const fields = [
    `position=${JSON.stringify(p.position)}`,
    `tripped=${p.tripped}`,
    `scan_monotonic_s=${p.scan_monotonic_s}`
];
if (p.requested_state != null) fields.push(`requested_state=${JSON.stringify(p.requested_state)}`);
if (p.actual_state != null) fields.push(`actual_state=${JSON.stringify(p.actual_state)}`);
if (typeof p.success === "boolean") fields.push(`success=${p.success}`);
if (p.cause != null) fields.push(`cause=${JSON.stringify(p.cause)}`);
msg.payload = `ied_event,ied=${tag(p.ied)},breaker=${tag(p.breaker)},event=${tag(p.event)},event_id=${tag(p.event_id)} ${fields.join(",")} ${timestamp}`;
return msg;

// Share one validator between the operational view and the historian.
const identities = ['BRK_F1', 'BRK_R1'];
if (msg.topic === 'status/bootstrap') {
    const missing = identities.filter(id => !context.get('seen_' + id));
    return [missing.map(breaker => ({topic: 'display/breaker', payload: {breaker, valid: false, status: null}})), null];
}
const breaker = String(msg.topic || '').replace(/^status\/breaker\//, '');
if (!identities.includes(breaker) || msg.topic !== 'status/breaker/' + breaker) {
    node.warn('Ignoring status on unexpected topic');
    return null;
}
context.set('seen_' + breaker, true);
let p;
try { p = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; }
catch (_) { p = null; }
const valid = !!(p && typeof p === 'object' && !Array.isArray(p) &&
    p.breaker === breaker && (p.state === 'OPEN' || p.state === 'CLOSED') &&
    typeof p.tripped === 'boolean' && typeof p.undervoltage_alarm === 'boolean' &&
    (p.trip_reason === null || typeof p.trip_reason === 'string') &&
    typeof p.ts === 'string' && Number.isFinite(Date.parse(p.ts)));
if (!valid) node.warn('Ignoring malformed status for ' + breaker);
return [{topic: 'display/breaker', payload: {breaker, valid, status: valid ? p : null}},
    valid ? {payload: p} : null];

if (msg.error) {
    node.warn('Influx write transport error: ' + String(msg.error.message || msg.error));
} else if (!Number.isInteger(msg.statusCode) || msg.statusCode < 200 || msg.statusCode >= 300) {
    node.warn('Influx write HTTP status ' + String(msg.statusCode));
}
return null;

// Complete snapshots keep all clients consistent, including on refresh.
const specs = [
    ['GRID_110KV', 'buses', ['vm_pu']],
    ['T1_PRIMARY', 'transformers', ['loading_percent']],
    ['BUS_MV_SOURCE', 'buses', ['vm_pu']],
    ['L1_FEEDER_HEAD', 'lines', ['i_ka', 'p_mw', 'q_mvar']],
    ['BUS_R1_REMOTE', 'buses', ['vm_pu']],
    ['L2_FEEDER_TAIL', 'lines', ['i_ka', 'p_mw', 'q_mvar']],
    ['BUS_SS1_MV', 'buses', ['vm_pu']],
    ['T2_SS1', 'transformers', ['loading_percent']],
    ['BUS_SS1_LV', 'buses', ['vm_pu']]
];
let state = flow.get('feederDisplay') || {
    presence: 'UNKNOWN', telemetryTs: null, receivedAt: null, assets: {},
    breakers: {BRK_F1: {valid: false, status: null}, BRK_R1: {valid: false, status: null}}
};
function quality(record) {
    if (record && record.energized === true && record.quality === 'GOOD') return 'ENERGIZED';
    if (record && record.energized === false && record.quality === 'NOT_ENERGIZED') return 'DE-ENERGIZED';
    return 'UNKNOWN';
}
if (msg.topic === 'telemetry/pandapower') {
    let p;
    try { p = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; }
    catch (_) { p = null; }
    const valid = p && typeof p.ts === 'string' && Number.isFinite(Date.parse(p.ts));
    const assets = {};
    for (const [name, collection, fields] of specs) {
        const records = valid && Array.isArray(p[collection]) ? p[collection].filter(r => r && r.name === name) : [];
        let record = records.length === 1 ? records[0] : null;
        let supply = quality(record);
        if (collection === 'lines') {
            const from = records.filter(r => r.end === 'from');
            const to = records.filter(r => r.end === 'to');
            record = from.length === 1 && to.length === 1 && records.length === 2 ? from[0] : null;
            supply = record && quality(record) === quality(to[0]) ? quality(record) : 'UNKNOWN';
        }
        const values = {};
        for (const field of fields) values[field] = supply !== 'UNKNOWN' &&
            typeof record[field] === 'number' && Number.isFinite(record[field]) ? record[field] : null;
        assets[name] = {supply, values};
    }
    state = {...state, presence: 'ONLINE', telemetryTs: valid ? p.ts : null, receivedAt: Date.now(), assets};
} else if (msg.topic === 'display/breaker') {
    const p = msg.payload;
    if (!p || !Object.hasOwn(state.breakers, p.breaker)) return null;
    state = {...state, breakers: {...state.breakers, [p.breaker]: {valid: p.valid === true, status: p.status}}};
} else if (msg.topic === 'display/presence') {
    // ONLINE is established by the sample itself, never by resurrecting cached values.
    if (msg.payload !== 'OFFLINE') return null;
    state = {...state, presence: 'OFFLINE'};
} else if (msg.topic !== 'display/bootstrap') return null;
flow.set('feederDisplay', state);
const current = state.presence === 'ONLINE' && state.receivedAt !== null && Date.now() - state.receivedAt < 5000;
const presence = state.presence === 'ONLINE' && !current ? 'OFFLINE' : state.presence;
const assets = {};
for (const [name, , fields] of specs) {
    const asset = state.assets[name] || {supply: 'UNKNOWN', values: {}};
    assets[name] = {supply: current ? asset.supply : presence, values: {}};
    for (const field of fields) assets[name].values[field] = current ? (asset.values[field] ?? null) : null;
}
const breakers = {};
for (const [id, entry] of Object.entries(state.breakers)) {
    const status = entry.valid ? entry.status : null;
    breakers[id] = {
        valid: entry.valid, status, enabled: current && entry.valid,
        position: status ? status.state : 'UNKNOWN',
        latch: status ? (status.tripped ? 'TRIPPED' : 'CLEAR') : 'UNKNOWN',
        reason: status ? status.trip_reason : null,
        alarm: status ? (status.undervoltage_alarm ? 'UV ALARM' : 'UV NORMAL') : 'UNKNOWN'
    };
}
return {topic: 'display/snapshot', payload: {presence, telemetryTs: state.telemetryTs,
    receivedAt: state.receivedAt, telemetryAgeMs: state.receivedAt === null ? null : Math.max(0, Date.now() - state.receivedAt), assets, breakers}};

// Display input and refresh are never commands. Interlocks remain in the IED.
if (msg.intent !== 'operator-command') return null;
const match = /^cmd\/breaker\/(BRK_F1|BRK_R1)\/(open|close|reset)$/.exec(msg.topic || '');
if (!match) return null;
const state = flow.get('feederDisplay');
if (!state || state.presence !== 'ONLINE' || state.receivedAt === null ||
    Date.now() - state.receivedAt >= 5000 || !state.breakers[match[1]].valid) {
    node.warn('Ignoring operator command while feedback is unavailable');
    return null;
}
return {topic: msg.topic, payload: match[2].toUpperCase()};
